// Elemental recipe database. Data only: no game logic lives here.
//
// ELEMENTS: every element in the game. `id` is the stable save key (never rename one), `icon` is
// an emoji, `category` is a CATEGORIES id, `desc` is the encyclopedia blurb.
//
// RECIPES: [a, b, result] combines a and b in either order. An object
// { a, b, result, ordered: true } only works when a is dropped onto b; the reverse drop is a
// separate pair that can make something else (or nothing).

export const STARTING = ['air', 'water', 'earth', 'fire'];

